INSERT INTO `wp_trp_gettext_vi` (`id`, `original`, `translated`, `domain`, `status`, `original_id`, `plural_form`) VALUES
(1,	'Index',	'Trang chính',	'default',	4,	1,	0),
(2,	'Used as a fallback template for all pages when a more specific template is not defined.',	'Được sử dụng như một mẫu dự phòng cho tất cả các trang khi không xác định mẫu cụ thể.',	'default',	4,	2,	0),
(3,	'Blog Home',	'Trang chủ blog',	'default',	4,	3,	0),
(4,	'Displays the latest posts as either the site homepage or as the \"Posts page\" as defined under reading settings. If it exists, the Front Page template overrides this template when posts are shown on the homepage.',	'Hiển thị các bài viết mới nhất dưới dạng trang chủ trang web hoặc dưới dạng “Trang bài viết” như được xác định dưới cài đặt đọc. Nếu tồn tại, mẫu trang chủ sẽ ghi đè lên mẫu này khi các bài viết được hiển thị trên trang chủ.',	'default',	4,	4,	0),
(5,	'Front Page',	'Trang chủ',	'default',	4,	5,	0),
(6,	'Displays your site\'s homepage, whether it is set to display latest posts or a static page. The Front Page template takes precedence over all templates.',	'Hiển thị trang chủ của trang web của bạn, cho dù nó được đặt để hiển thị bài viết mới nhất hoặc một trang tĩnh. Mẫu Trang chủ ưu tiên hơn tất cả các mẫu.',	'default',	4,	6,	0),
(7,	'Single Entries',	'Các mục đơn',	'default',	4,	7,	0),
(8,	'Displays any single entry, such as a post or a page. This template will serve as a fallback when a more specific template (e.g. Single Post, Page, or Attachment) cannot be found.',	'Hiển thị bất kỳ mục đơn nào, chẳng hạn như một bài viết hoặc một trang. Mẫu này sẽ phục vụ như một mẫu dự phòng khi không thể tìm thấy mẫu cụ thể hơn (ví dụ: bài viết đơn, trang, hoặc đính kèm).',	'default',	4,	8,	0),
(9,	'Single Posts',	'Các bài viết',	'default',	4,	9,	0),
(10,	'Displays a single post on your website unless a custom template has been applied to that post or a dedicated template exists.',	'Hiển thị một bài viết duy nhất trên trang web của bạn trừ khi một mẫu tùy chỉnh đã được áp dụng cho bài viết đó hoặc một mẫu chuyên dụng tồn tại.',	'default',	4,	10,	0),
(11,	'Pages',	'Trang',	'default',	4,	11,	0),
(12,	'Displays a static page unless a custom template has been applied to that page or a dedicated template exists.',	'Hiển thị một trang tĩnh trừ khi một mẫu tùy chỉnh đã được áp dụng cho trang đó hoặc một mẫu chuyên dụng tồn tại.',	'default',	4,	12,	0),
(13,	'All Archives',	'Lưu trữ tất cả',	'default',	4,	13,	0),
(14,	'Displays any archive, including posts by a single author, category, tag, taxonomy, custom post type, and date. This template will serve as a fallback when more specific templates (e.g. Category or Tag) cannot be found.',	'Hiển thị bất kỳ lưu trữ nào, bao gồm bài viết của một tác giả duy nhất, danh mục, thẻ, phân loại, loại bài viết tùy chỉnh và ngày. Mẫu này sẽ phục vụ như một mẫu dự phòng khi không thể tìm thấy mẫu cụ thể hơn (ví dụ: Danh mục hoặc Thẻ).',	'default',	4,	14,	0),
(15,	'Author Archives',	'Lưu trữ tác giả',	'default',	4,	15,	0),
(16,	'Displays a single author\'s post archive. This template will serve as a fallback when a more specific template (e.g. Author: Admin) cannot be found.',	'Hiển thị lưu trữ bài viết của một tác giả duy nhất. Mẫu này sẽ phục vụ như một mẫu dự phòng khi không thể tìm thấy mẫu cụ thể hơn (ví dụ: Tác giả: Admin).',	'default',	4,	16,	0),
(17,	'Category Archives',	'Lưu trữ danh mục',	'default',	4,	17,	0),
(18,	'Displays a post category archive. This template will serve as a fallback when a more specific template (e.g. Category: Recipes) cannot be found.',	'Hiển thị kho lưu trữ danh mục bài đăng. Mẫu này sẽ đóng vai trò dự phòng khi không tìm thấy mẫu cụ thể hơn (ví dụ: Danh mục: Công thức nấu ăn).',	'default',	4,	18,	0),
(19,	'Taxonomy',	'Phân loại',	'default',	4,	19,	0),
(20,	'Displays a custom taxonomy archive. Like categories and tags, taxonomies have terms which you use to classify things. For example: a taxonomy named \"Art\" can have multiple terms, such as \"Modern\" and \"18th Century.\" This template will serve as a fallback when a more specific template (e.g. Taxonomy: Art) cannot be found.',	'Hiển thị lưu trữ phân loại tùy chỉnh. Giống như danh mục và thẻ, phân loại có các thuật ngữ mà bạn sử dụng để phân loại các thứ. Ví dụ: một phân loại có tên “Nghệ thuật” có thể có nhiều thuật ngữ, chẳng hạn như “Hiện đại” và “Thế kỷ 18”. Mẫu này sẽ phục vụ như một mẫu dự phòng khi không thể tìm thấy mẫu cụ thể hơn (ví dụ: Phân loại: Nghệ thuật).',	'default',	4,	20,	0),
(21,	'Date Archives',	'Ngày lưu trữ',	'default',	4,	21,	0),
(22,	'Displays a post archive when a specific date is visited (e.g., example.com/2023/).',	'Hiển thị trang lưu trữ bài viết khi một ngày cụ thể được truy cập (ví dụ: example.com/2023/).',	'default',	4,	22,	0),
(23,	'Tag Archives',	'Lưu trữ thẻ',	'default',	4,	23,	0),
(24,	'Displays a post tag archive. This template will serve as a fallback when a more specific template (e.g. Tag: Pizza) cannot be found.',	'Hiển thị lưu trữ thẻ bài viết. Mẫu này sẽ phục vụ như một mẫu dự phòng khi không thể tìm thấy mẫu cụ thể hơn (ví dụ: Thẻ: Pizza).',	'default',	4,	24,	0),
(25,	'Attachment Pages',	'Trang đính kèm',	'default',	4,	25,	0),
(26,	'Displays when a visitor views the dedicated page that exists for any media attachment.',	'Hiển thị khi khách truy cập xem trang dành riêng cho bất kỳ tệp đính kèm đa phương tiện.',	'default',	4,	26,	0),
(27,	'Search Results',	'Kết quả tìm kiếm',	'default',	4,	27,	0),
(28,	'Displays when a visitor performs a search on your website.',	'Hiển thị khi một khách truy cập thực hiện tìm kiếm trên website của bạn.',	'default',	4,	28,	0),
(29,	'Privacy Policy',	'Chính sách bảo mật',	'default',	4,	29,	0),
(30,	'Displays your site\'s Privacy Policy page.',	'Hiển thị trang Chính sách bảo mật của trang web của bạn.',	'default',	4,	30,	0),
(31,	'Page: 404',	'Trang: 404',	'default',	4,	31,	0),
(32,	'Displays when a visitor views a non-existent page, such as a dead link or a mistyped URL.',	'Hiển thị khi khách truy cập xem một trang không tồn tại, ví dụ như liên kết không hoạt động hoặc nhập sai URL.',	'default',	4,	32,	0),
(33,	'Standard',	'Chuẩn',	'default',	4,	33,	0),
(34,	'Aside',	'Đứng riêng',	'default',	4,	34,	0),
